function promptDirty(){return !S.dirty || confirm('Bạn chưa lưu thay đổi. Bỏ thay đổi để chuyển ảnh?')}
const copyBoxes=()=>JSON.parse(JSON.stringify(S.editor?.boxes||[]));
function snapshot(){if(S.editor){S.undo.push(copyBoxes());if(S.undo.length>60)S.undo.shift();S.redo=[]}}
function commitChange(){S.dirty=true;refreshInspector();drawCanvas()}
function undoRedo(kind){if(S.readonly)return;let from=kind==='undo'?S.undo:S.redo,to=kind==='undo'?S.redo:S.undo;if(!from.length)return;to.push(copyBoxes());S.editor.boxes=from.pop();S.selected=null;commitChange()}
async function releaseEditor(){clearInterval(S.heartbeat);S.heartbeat=null;if(S.editor && S.lease){try{await send('POST',`/projects/${S.project.id}/assets/${S.editor.id}/unlock`)}catch{}}S.editor=null;S.img=null;S.lease=false}
async function openAsset(id){if(S.dirty&&S.autosave){await saveImage(false)}else if(!promptDirty())return;await releaseEditor();
 let p=S.project.id;let lease=false;const canEdit=['owner','manager','editor'].includes(S.project.role);if(canEdit){try{await send('POST',`/projects/${p}/assets/${id}/lock`);lease=true}catch(e){toast(e.message+' — read-only',true)}}
 let info;try{info=await api(`/projects/${p}/assets/${id}`)}catch(e){if(lease){await send('POST',`/projects/${p}/assets/${id}/unlock`).catch(()=>{})}throw e}
 S.lease=lease;S.readonly=!lease;S.editor=info;S.selected=null;S.zoom=1;S.pan={x:0,y:0};S.dirty=false;S.undo=[];S.redo=[];S.editMode='select';S.drawClass=0;
 const im=new Image();im.onload=()=>{if(S.editor?.id===id){S.img=im;renderEditor()}};im.onerror=()=>toast('Lỗi tải ảnh từ máy chủ',true);im.src=`/api/projects/${p}/assets/${id}/image`;
 S.heartbeat=setInterval(async()=>{if(S.lease && S.editor){try{await send('POST',`/projects/${p}/assets/${S.editor.id}/lock`)}catch(e){S.lease=false;S.readonly=true;toast('Đã mất khóa ảnh; không thể lưu cho đến khi mở lại',true);renderEditor()}}},65000)
}
function editorRail(){let list=S.assets.filter(a=>!S.railQuery || a.image_rel.toLowerCase().includes(S.railQuery.toLowerCase()));return `<aside class="asset-rail"><div class="rail-head"><div class="row between"><strong style="font-size:13px">Image queue</strong><span class="tag">${S.total}</span></div><div class="searchwrap" style="margin-top:12px"><span>${ic('search')}</span><input class="field" style="font-size:11px;padding-top:9px;padding-bottom:9px" id="rail-search" value="${html(S.railQuery)}" placeholder="Find in current page"></div></div><div class="rail-scroller" id="rail-content">${railItems(list)}</div></aside>`}
function railItems(list){return list.map(a=>`<div class="rail-item ${S.editor?.id===a.id?'selected':''}" data-action="openAsset" data-id="${a.id}"><img class="rail-thumb" loading="lazy" src="/api/projects/${S.project.id}/assets/${a.id}/thumbnail" alt=""><div style="min-width:0"><div class="rail-name" title="${html(a.image_rel)}">${html(filename(a.image_rel))}</div><div class="rail-meta">${a.state==='reviewed'?'✓ '+html(a.reviewed_by||'Reviewed'):a.state==='in_progress'?'◐ In progress':'○ To do'}${a.lock?' · 🔒':''}</div></div></div>`).join('')}
function boxClass(name,i,active=false){return `<button class="class-row ${active?'box-row selected':''}" data-action="chooseClass" data-id="${i}"><span><span class="class-dot" style="background:${color(i)}"></span> ${html(name)}</span><span class="tag">${i}</span></button>`}
function inspectorHTML(){const a=S.editor,sel=S.selected!=null?a.boxes[S.selected]:null;const W=a.width,H=a.height;
 const coords=sel?(()=>{const c=boxEdges(sel);return [c.x1*W,c.y1*H,c.x2*W,c.y2*H]})():[0,0,0,0];
 return `<div class="inspector-head"><div class="row between"><strong>Annotation panel</strong><span class="tag">${a.boxes.length} boxes</span></div><p class="tiny muted" style="margin-bottom:0">${S.readonly?'Read-only mode':'Click bounding box to inspect & edit'}</p></div><div class="inspector-section"><div class="inspector-title">Label classes <span class="tag">${S.project.classes.length}</span></div>${S.project.classes.map((n,i)=>boxClass(n,i,sel?sel.cls===i:S.drawClass===i)).join('')}</div><div class="inspector-section"><div class="inspector-title">Objects <span>${a.boxes.length}</span></div><div style="max-height:180px;overflow:auto">${a.boxes.map((b,i)=>`<button class="class-row box-row ${S.selected===i?'selected':''}" data-action="chooseBox" data-id="${i}"><span>${html(`#${i+1}`)} <span class="class-dot" style="background:${boxColor(b,i)}"></span>${html(S.project.classes[b.cls])}</span>${S.selected===i?'●':ic('target','sm')}</button>`).join('')||'<p class="small-muted">No bounding boxes in this image.</p>'}</div></div><div class="inspector-section"><div class="inspector-title">Coordinates <span class="tag">pixels</span></div>${sel?`<div class="coordinate-grid">${['X min','Y min','X max','Y max'].map((lbl,i)=>`<label>${lbl}<input class="field coord" id="coord${i}" type="number" min="0" step="0.1" value="${coords[i].toFixed(1)}" ${S.readonly?'disabled':''}></label>`).join('')}</div><div class="row" style="margin-top:11px">${btn('Apply coordinates','applyCoords','quiet small',S.readonly?'disabled':'')}${btn(ic('trash')+' Delete','deleteBox','danger small',S.readonly?'disabled':'')}</div>`:'<p class="small-muted">Select a box to edit its position.</p>'}</div><div class="inspector-section"><div class="inspector-title">Review status</div>${a.state==='reviewed'&&a.reviewed_by?`<p class="tiny" style="color:#4fdec1">✓ Đã hoàn thành bởi <b>${html(a.reviewed_by)}</b><br>${a.reviewed_at?new Date(a.reviewed_at*1000).toLocaleString('vi-VN'):''}</p>`:''}<select id="review-state" class="field" ${S.readonly?'disabled':''}><option value="todo" ${a.state==='todo'?'selected':''}>○ To do</option><option value="in_progress" ${a.state==='in_progress'?'selected':''}>◐ In progress</option><option value="reviewed" ${a.state==='reviewed'?'selected':''}>✓ Reviewed</option></select><div style="margin-top:13px">${btn(ic('history')+' Version history','history','quiet small')}</div></div><div class="inspector-section"><div class="inspector-title">Keyboard shortcuts</div><div class="help-note"><span class="kbd">V</span> Select / Move &nbsp; <span class="kbd">B</span> Draw<br><span class="kbd">Del</span> Delete &nbsp; <span class="kbd">Ctrl+Z</span> Undo<br><span class="kbd">Ctrl+S</span> Save</div></div>`}
function renderEditor(){S.view='editor';const a=S.editor,items=S.assets.map(x=>x.id),i=items.indexOf(a.id);
 shell(`<div class="editor"><div class="editor-top"><div class="row" style="min-width:0">${btn(ic('back'),'backProject','ghost icon-btn')}<div><div class="filename">${html(filename(a.image_rel))}</div><div class="small-muted">${html(a.split)} / Revision ${a.revision} / ${i>=0?i+1:'—'} of ${S.total}</div></div></div><div class="row">${a.lock?`<span class="tag ${S.lease?'green':'red'}">${ic('lock','sm')} ${S.lease?'Your lock':html(a.lock.name)}</span>`:'<span class="tag">Not locked</span>'}${S.dirty?'<span class="tag orange">● Unsaved</span>':''}${btn(ic('back'),'previousAsset','quiet icon-btn')}${btn(ic('arrow'),'nextAsset','quiet icon-btn')}${btn(ic('save')+' Save','save','quiet',S.readonly?'disabled':'')}${btn(ic('check')+' Hoàn thành ✓','completeAsset','primary',S.readonly?'disabled':'')}${btn('Save & next','saveNext','quiet',S.readonly?'disabled':'')}</div></div><div class="editor-main">${editorRail()}<div class="editor-center"><div class="toolstrip">${btn(ic('cursor')+' Select','modeSelect',S.editMode==='select'?'active small':'quiet small',S.readonly?'disabled':'')}${btn(ic('target')+' Draw box','modeDraw',S.editMode==='draw'?'active small':'quiet small',S.readonly?'disabled':'')}<div class="separator"></div>${btn(ic('undo'),'undo','quiet icon-btn',!S.undo.length||S.readonly?'disabled':'')}${btn(ic('redo'),'redo','quiet icon-btn',!S.redo.length||S.readonly?'disabled':'')}<span class="grow"></span>${btn('−','zoomOut','quiet icon-btn')}${btn(`${Math.round(S.zoom*100)}%`,'resetZoom','quiet small')}${btn('+','zoomIn','quiet icon-btn')}</div><div id="canvas-area" class="canvas-container"><canvas id="edit-canvas"></canvas><div class="canvas-help">${S.readonly?'VIEW ONLY — another editor may have the lock':'V Select / B Draw · drag corners to resize · hold Space to pan · scroll to zoom'}</div></div><div class="canvas-info"><span>${a.width} × ${a.height} px &nbsp; · &nbsp; ${a.boxes.length} labels</span><span>${html(a.label_rel)} &nbsp; | &nbsp; ${S.dirty?'● Unsaved':'✓ Synced'}</span></div></div><aside class="inspector" id="inspector">${inspectorHTML()}</aside></div></div>`, S.project.name);
 requestAnimationFrame(()=>{bindCanvas();installColorMode()})}
function refreshInspector(){if(S.view!=='editor')return;const pane=el('inspector');if(pane)pane.innerHTML=inspectorHTML();const unsaved=el('canvas-area')?.parentNode?.querySelector('.canvas-info');if(unsaved)unsaved.innerHTML=`<span>${S.editor.width} × ${S.editor.height} px &nbsp; · &nbsp; ${S.editor.boxes.length} labels</span><span>${html(S.editor.label_rel)} &nbsp;|&nbsp; ${S.dirty?'● Unsaved':'✓ Synced'}</span>`}
function boxEdges(b){return {x1:b.x-b.w/2,y1:b.y-b.h/2,x2:b.x+b.w/2,y2:b.y+b.h/2}}
function fromEdges(c,cls){return {cls,x:(c.x1+c.x2)/2,y:(c.y1+c.y2)/2,w:c.x2-c.x1,h:c.y2-c.y1}}
const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
function canvasGeometry(){const canvas=el('edit-canvas'),r=canvas?.getBoundingClientRect();if(!r||!S.img)return null;const sc=Math.min((r.width-44)/S.img.width,(r.height-44)/S.img.height)*S.zoom;return {canvas,r,sc,px:(r.width-S.img.width*sc)/2+S.pan.x,py:(r.height-S.img.height*sc)/2+S.pan.y}}
function toCanvas(g,x,y){return {x:g.px+x*S.img.width*g.sc,y:g.py+y*S.img.height*g.sc}}
function fromCanvas(g,x,y){return {x:clamp((x-g.px)/(S.img.width*g.sc)),y:clamp((y-g.py)/(S.img.height*g.sc))}}
function drawCanvas(){if(S.view!=='editor'||!S.img)return;const g=canvasGeometry();if(!g)return;const {canvas,r,sc,px,py}=g,dpr=window.devicePixelRatio||1;canvas.width=Math.max(1,Math.round(r.width*dpr));canvas.height=Math.max(1,Math.round(r.height*dpr));const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,r.width,r.height);ctx.drawImage(S.img,px,py,S.img.width*sc,S.img.height*sc);
 S.editor.boxes.forEach((b,i)=>{const c=boxEdges(b),p1=toCanvas(g,c.x1,c.y1),p2=toCanvas(g,c.x2,c.y2),x=p1.x,y=p1.y,w=p2.x-p1.x,h=p2.y-p1.y,selected=S.selected===i,col=boxColor(b,i);ctx.strokeStyle=col;ctx.lineWidth=selected?3:2;ctx.strokeRect(x,y,w,h);if(selected){ctx.fillStyle=col+'21';ctx.fillRect(x,y,w,h);[p1,{x:p2.x,y:p1.y},{x:p1.x,y:p2.y},p2].forEach(p=>{ctx.fillStyle='#fff';ctx.fillRect(p.x-5,p.y-5,10,10);ctx.strokeStyle=col;ctx.strokeRect(p.x-5,p.y-5,10,10)})}if(S.colorMode!=='box'){const label=(i+1)+'  '+(S.project.classes[b.cls]||'Class '+b.cls);ctx.font='700 12px Segoe UI, Arial';const tw=ctx.measureText(label).width+14;const above=y>=25?y-24:y;ctx.fillStyle=col;ctx.fillRect(x,above,tw,23);ctx.fillStyle='#06101a';ctx.fillText(label,x+7,above+16)}})}
function hitBox(g,x,y){for(let i=S.editor.boxes.length-1;i>=0;i--){const b=S.editor.boxes[i],c=boxEdges(b),p1=toCanvas(g,c.x1,c.y1),p2=toCanvas(g,c.x2,c.y2);for(const [key,p] of Object.entries({tl:p1,tr:{x:p2.x,y:p1.y},bl:{x:p1.x,y:p2.y},br:p2})){if(Math.abs(x-p.x)<11&&Math.abs(y-p.y)<11)return {i,kind:key}}
 if(x>=p1.x&&x<=p2.x&&y>=p1.y&&y<=p2.y)return {i,kind:'move'}}return null}
function bindCanvas(){const c=el('edit-canvas');if(!c||!S.img)return;drawCanvas();let spaceHeld=false;
 // These listeners attach to the new canvas element after each full render.
 c.onpointerdown=e=>{if(e.button!==0)return;const g=canvasGeometry();if(!g)return;const r=c.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,pt=fromCanvas(g,x,y);
 if(e.shiftKey){S.drag={kind:'pan',x,y,pan:{...S.pan}};c.setPointerCapture(e.pointerId);return}
 if(S.readonly)return;
 if(S.editMode==='draw') {snapshot();const b={cls:S.drawClass,x:pt.x,y:pt.y,w:0,h:0};S.editor.boxes.push(b);S.selected=S.editor.boxes.length-1;S.drag={kind:'draw',origin:pt};}
 else {const hit=hitBox(g,x,y);S.selected=hit?.i??null;if(hit){snapshot();S.drag={kind:hit.kind,origin:pt,old:{...S.editor.boxes[hit.i]}}}}
 if(S.drag)c.setPointerCapture(e.pointerId);refreshInspector();drawCanvas()};
 c.onpointermove=e=>{if(!S.drag)return;const g=canvasGeometry(),r=c.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(S.drag.kind==='pan'){S.pan={x:S.drag.pan.x+x-S.drag.x,y:S.drag.pan.y+y-S.drag.y};drawCanvas();return}
 const pt=fromCanvas(g,x,y),d=S.drag,b=S.editor.boxes[S.selected];if(!b)return;const minX=1/S.editor.width,minY=1/S.editor.height;
 if(d.kind==='draw'){const x1=Math.min(pt.x,d.origin.x),x2=Math.max(pt.x,d.origin.x),y1=Math.min(pt.y,d.origin.y),y2=Math.max(pt.y,d.origin.y);Object.assign(b,fromEdges({x1,y1,x2,y2},b.cls))}
 else if(d.kind==='move'){const old=boxEdges(d.old);let dx=pt.x-d.origin.x,dy=pt.y-d.origin.y;dx=clamp(dx,-old.x1,1-old.x2);dy=clamp(dy,-old.y1,1-old.y2);Object.assign(b,fromEdges({x1:old.x1+dx,x2:old.x2+dx,y1:old.y1+dy,y2:old.y2+dy},b.cls))}
 else{const z=boxEdges(d.old);if(d.kind.includes('l'))z.x1=clamp(pt.x,0,z.x2-minX);if(d.kind.includes('r'))z.x2=clamp(pt.x,z.x1+minX,1);if(d.kind.includes('t'))z.y1=clamp(pt.y,0,z.y2-minY);if(d.kind.includes('b'))z.y2=clamp(pt.y,z.y1+minY,1);Object.assign(b,fromEdges(z,b.cls))}S.dirty=true;drawCanvas()};
 c.onpointerup=e=>{if(!S.drag)return;const d=S.drag;S.drag=null;if(d.kind==='draw'&&S.selected!=null){const b=S.editor.boxes[S.selected];if(b.w<3/S.editor.width||b.h<3/S.editor.height){S.editor.boxes.splice(S.selected,1);S.selected=null}}refreshInspector();drawCanvas()};
 c.onpointercancel=c.onpointerup;
 c.onwheel=e=>{e.preventDefault();S.zoom=clamp(S.zoom*(e.deltaY<0?1.1:1/1.1),0.35,5);drawCanvas()};
 new ResizeObserver(()=>{if(c.isConnected)drawCanvas()}).observe(c);
}
async function saveImage(next=false){if(S.readonly){toast('Không có quyền sửa ảnh hoặc khóa đã hết hạn',true);return}if(!S.editor)return;const id=S.editor.id,pid=S.project.id;
 const d=await send('PATCH',`/projects/${pid}/assets/${id}/annotations`,{revision:S.editor.revision,boxes:S.editor.boxes,state:S.editor.state});S.editor.revision=d.revision;S.editor.state=d.state;S.dirty=false;
 const a=S.assets.find(a=>a.id===id);if(a){a.revision=d.revision;a.state=d.state;a.updated_by=S.user.display_name;a.reviewed_by=d.state==='reviewed'?S.user.display_name:null;a.reviewed_at=d.state==='reviewed'?Math.floor(Date.now()/1000):null;}S.editor.updated_by=S.user.display_name;S.editor.reviewed_by=d.state==='reviewed'?S.user.display_name:null;S.editor.reviewed_at=d.state==='reviewed'?Math.floor(Date.now()/1000):null;S.projects=await api(`/workspaces/${S.wid}/projects`);toast('✓ Saved YOLO annotations');if(next){await navigateAsset(1)}else renderEditor()}
async function completeAsset(){if(!S.editor||S.readonly)return;S.editor.state='reviewed';S.dirty=true;await saveImage(true);toast('✓ Đã đánh dấu hoàn thành và lưu người review')}
async function navigateAsset(delta){let ids=S.assets.map(a=>a.id),i=ids.indexOf(S.editor?.id);if(i<0)return;const idx=i+delta;if(idx<0||idx>=ids.length){toast('Hết danh sách hiện tại; quay lại Dataset để đổi trang');return}await openAsset(ids[idx])}
function deleteBox(){if(S.readonly||S.selected==null)return;snapshot();S.editor.boxes.splice(S.selected,1);S.selected=null;commitChange()}
function applyCoords(){if(S.readonly||S.selected==null)return;let nums=[0,1,2,3].map(i=>Number(el('coord'+i)?.value));const [x1,y1,x2,y2]=nums,W=S.editor.width,H=S.editor.height;
 if(nums.some(n=>!Number.isFinite(n))||x1<0||y1<0||x2>W||y2>H||x2<=x1||y2<=y1){toast('Tọa độ pixel không hợp lệ',true);return}snapshot();S.editor.boxes[S.selected]=fromEdges({x1:x1/W,y1:y1/H,x2:x2/W,y2:y2/H},S.editor.boxes[S.selected].cls);commitChange()}
async function showHistory(){const h=await api(`/projects/${S.project.id}/assets/${S.editor.id}/history`);modalOpen('Annotation history',`Recent saved versions for ${html(filename(S.editor.image_rel))}`,h.length?`<div style="max-height:350px;overflow:auto">${h.map(x=>`<div class="row between" style="border-bottom:1px solid #2b3950;padding:12px 0"><div>Revision ${x.revision} <span class="tag">${html(x.author)}</span></div><span class="tiny muted">${new Date(x.changed_at*1000).toLocaleString('vi-VN')}</span></div>`).join('')}</div>`:'<p>Chưa có phiên bản lưu.</p>','Close',async()=>{})}
const handlers={
 home:async()=>{if(S.view==='editor'&& !promptDirty())return;if(S.view==='editor')await releaseEditor();dashboard()},
 datasets:async()=>{if(S.view==='editor'&&!promptDirty())return;if(S.view==='editor')await releaseEditor();if(S.project)await reloadProject();else dashboard()},
 project:async e=>{if(S.view==='editor'&&!promptDirty())return;if(S.view==='editor')await releaseEditor();await openProject(Number(e.dataset.id))},
 newWorkspace, newProject,team:openTeam,newUser,newMember,
 closeModal:async()=>{modal.innerHTML=''},
 logout:async()=>{if(S.view==='editor'&&!promptDirty())return;if(S.editor)await releaseEditor();await send('POST','/auth/logout');S.user=null;S.csrf=null;renderLogin()},
 refreshProject:reloadProject,quality:checkQuality,exportProject,inferProject,pipeline:openPipeline,
 filterSplit:async e=>{S.split=e.dataset.value;S.page=1;await listAssets();projectPage()},
 prevPage:async()=>{S.page=Math.max(1,S.page-1);await listAssets();projectPage()},
 nextPage:async()=>{S.page+=1;await listAssets();projectPage()},
 openAsset:async e=>openAsset(Number(e.dataset.id)),deleteProject,deleteWorkspace,removeMember,
 backProject:async()=>{if(!promptDirty())return;await releaseEditor();await reloadProject()},
 previousAsset:()=>navigateAsset(-1),nextAsset:()=>navigateAsset(1),
 modeSelect:()=>{S.editMode='select';renderEditor()},modeDraw:()=>{S.editMode='draw';renderEditor()},
 chooseBox:e=>{S.selected=Number(e.dataset.id);refreshInspector();drawCanvas()},
 chooseClass:e=>{const i=Number(e.dataset.id);S.drawClass=i;if(S.selected!=null&&!S.readonly){snapshot();S.editor.boxes[S.selected].cls=i;commitChange()}else refreshInspector()},
 deleteBox,applyCoords,undo:()=>undoRedo('undo'),redo:()=>undoRedo('redo'),
 zoomIn:()=>{S.zoom=clamp(S.zoom*1.2,.35,5);drawCanvas();renderZoom()},
 zoomOut:()=>{S.zoom=clamp(S.zoom/1.2,.35,5);drawCanvas();renderZoom()},
 resetZoom:()=>{S.zoom=1;S.pan={x:0,y:0};drawCanvas();renderZoom()},
 save:()=>saveImage(false),saveNext:()=>saveImage(true),completeAsset,history:showHistory,
};
function installColorMode(){
 const tool=el('edit-canvas')?.parentNode?.previousElementSibling;
 if(!tool||tool.querySelector('#color-mode'))return;
 const wrap=document.createElement('label');
 wrap.className='tiny muted';
 wrap.innerHTML='Màu <select id="color-mode" class="field" style="width:auto;display:inline-block;padding:7px 9px"><option value="class">Theo lớp</option><option value="box">Mỗi khung</option><option value="single">Một màu</option></select>';
 tool.insertBefore(wrap,tool.querySelector('.grow'));
 wrap.querySelector('select').value=S.colorMode;
 wrap.querySelector('select').onchange=e=>{S.colorMode=e.target.value;drawCanvas();refreshInspector()};
 const auto=document.createElement('label');
 auto.className='tiny muted';
 auto.style.marginLeft='10px';
 auto.innerHTML='<input id="autosave-mode" type="checkbox" style="vertical-align:middle;margin-right:5px">Autosave';
 tool.insertBefore(auto,tool.querySelector('.grow'));
 auto.querySelector('input').checked=S.autosave;
 auto.querySelector('input').onchange=e=>{S.autosave=e.target.checked};
}
function renderZoom(){const tool=el('edit-canvas')?.parentNode?.previousElementSibling;if(tool){const b=tool.querySelector('[data-action=resetZoom]');if(b)b.textContent=Math.round(S.zoom*100)+'%'}installColorMode()}
document.addEventListener('click',e=>{if(e.target.matches('.overlay')){modal.innerHTML='';return}const target=e.target.closest('[data-action]');if(!target||target.disabled)return;const h=handlers[target.dataset.action];if(h)secureAction(h)(target)});
document.addEventListener('change',e=>{if(e.target.id==='workspace-picker')secureAction(async()=>{if(S.view==='editor'&&!promptDirty())return;if(S.editor)await releaseEditor();S.wid=Number(e.target.value);S.project=null;await loadWorkspace()})();if(e.target.id==='review-filter')secureAction(async()=>{S.state=e.target.value;S.page=1;await listAssets();projectPage()})();if(e.target.id==='review-state'&&S.editor){S.editor.state=e.target.value;S.dirty=true;refreshInspector()}});
let timer;
document.addEventListener('input',e=>{if(e.target.id==='project-search'){clearTimeout(timer);const value=e.target.value;timer=setTimeout(()=>secureAction(async()=>{S.query=value;S.page=1;await listAssets();projectPage();el('project-search')?.focus();el('project-search')?.setSelectionRange(value.length,value.length)})(),320)}
 if(e.target.id==='rail-search'){S.railQuery=e.target.value;const rail=el('rail-content');if(rail)rail.innerHTML=railItems(S.assets.filter(a=>a.image_rel.toLowerCase().includes(S.railQuery.toLowerCase())))}});
document.addEventListener('submit',e=>{if(e.target.id!=='login-form')return;e.preventDefault();secureAction(async()=>{const f=new FormData(e.target);const d=await send('POST','/auth/login',{username:f.get('username'),password:f.get('password')});S.user=d.user;S.csrf=d.csrf;await fetchWorkspaces();await loadWorkspace()})()});
document.addEventListener('keydown',e=>{if(S.view!=='editor')return;const typing=/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||'')||document.activeElement?.isContentEditable;if(typing)return;
 const cmd=e.ctrlKey||e.metaKey;if(cmd&&e.key.toLowerCase()==='s'){e.preventDefault();secureAction(()=>saveImage(false))();return}if(cmd&&e.key.toLowerCase()==='z'){e.preventDefault();undoRedo('undo');return}if(cmd&&e.key.toLowerCase()==='y'){e.preventDefault();undoRedo('redo');return}if(e.key==='ArrowLeft'){e.preventDefault();secureAction(()=>navigateAsset(-1))();return}if(e.key==='ArrowRight'){e.preventDefault();secureAction(()=>navigateAsset(1))();return}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteBox()}if(e.key.toLowerCase()==='v'&&!cmd){S.editMode='select';renderEditor()}if(e.key.toLowerCase()==='b'&&!cmd){S.editMode='draw';renderEditor()}});
window.addEventListener('beforeunload',e=>{if(S.dirty){e.preventDefault();e.returnValue=''}});
async function boot(){try{const d=await api('/auth/me');S.user=d.user;S.csrf=d.csrf;await fetchWorkspaces();await loadWorkspace()}catch{renderLogin()}}
boot();
